from threetears.evals import Eval

from desk import replay


def run_desk(case):
    """The ticket after its events, as the new desk leaves it."""
    ticket = replay(case["ticket"], case["events"])
    return {"status": ticket.status, "reopens": ticket.reopens}


def matches_old_desk(case, out):
    """The ticket ends where the old desk left it: its status and its reopen count."""
    return out == case["old_desk"]


export = Eval("data/export.jsonl", runner=run_desk, grader=[matches_old_desk], k=1)
